"""Sequential checkpoint, rewind, and do-again for derived KV state.

Branching is sequential, not copy-on-write.  A learner can checkpoint the
cache at a stable boundary, try one action, rewind to the boundary, and try
another action.  The honest KV lesson is unchanged: the unchanged prefix is
reused, only the divergent suffix is recomputed, and a rewind never rolls
back external world state.

This module deliberately does NOT implement concurrent forks, shared prefix
pages, refcounts, or a radix registry.  Those belong to a later extension
(COW/radix cache); the sequential model covers every learner scenario —
"what are you doing?" side queries, what-if exploration, undo/redo — with
``GenerationSession`` longest-prefix reuse plus an explicit rewind.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from .generation import GenerationSession


class RewindError(RuntimeError):
    """A sequential branch operation is invalid or unsafe."""


@dataclass(frozen=True)
class BranchStats:
    """Honest token/page accounting for one sequential branch attempt."""

    checkpoint_tokens: int
    reused_tokens: int
    rewound_tokens: int
    prefilled_tokens: int
    output_tokens: int
    cold_start: bool = False

    def to_dict(self) -> dict[str, int]:
        return {
            "checkpoint_tokens": self.checkpoint_tokens,
            "reused_tokens": self.reused_tokens,
            "rewound_tokens": self.rewound_tokens,
            "prefilled_tokens": self.prefilled_tokens,
            "output_tokens": self.output_tokens,
            "cold_start": int(self.cold_start),
        }


class SequentialBranch:
    """Checkpoint -> act -> rewind -> do again, over one generation session.

    The branch owns a single ``GenerationSession``.  ``checkpoint()`` records
    the exact cached token prefix at a stable boundary; ``act()`` runs one
    generation turn from the current cache state; ``rewind()`` discards the
    cache tail back to the boundary (reusing the unchanged prefix);
    ``do_again()`` rewinds and runs a different turn from the same boundary.
    Closing the branch releases the session.
    """

    def __init__(self, session: "GenerationSession"):
        self._session = session
        self._checkpoint_tokens: tuple[int, ...] | None = None
        self._closed = False

    @property
    def session(self) -> "GenerationSession":
        return self._session

    @property
    def checkpoint_tokens(self) -> tuple[int, ...] | None:
        return self._checkpoint_tokens

    def checkpoint(self) -> tuple[int, ...]:
        """Record the exact cached token prefix as the branch boundary."""

        if self._closed:
            raise RewindError("cannot checkpoint a closed branch")
        tokens = self._session.cached_token_ids
        if not tokens:
            raise RewindError("cannot checkpoint a cold cache")
        self._checkpoint_tokens = tokens
        return tokens

    def act(self, messages: list[dict[str, str]]) -> tuple[str, BranchStats]:
        """Run one generation turn, then report the honest token accounting."""

        if self._closed:
            raise RewindError("cannot act on a closed branch")
        if self._checkpoint_tokens is None:
            raise RewindError("checkpoint() must precede act()")
        output = self._session(messages)
        stats = self._session.last_stats
        return output, BranchStats(
            checkpoint_tokens=len(self._checkpoint_tokens),
            reused_tokens=stats.reused_tokens,
            rewound_tokens=stats.rewound_tokens,
            prefilled_tokens=stats.prefilled_tokens,
            output_tokens=stats.output_tokens,
            cold_start=stats.cold_start,
        )

    def rewind(self) -> int:
        """Restore the cache exactly to the checkpoint boundary.

        Only the divergent suffix is discarded: the unchanged prefix stays
        cached and is reused by the next ``act``.  Rewinding the cache never
        rewinds the world; callers must reconcile external state separately.
        """

        if self._closed:
            raise RewindError("cannot rewind a closed branch")
        if self._checkpoint_tokens is None:
            raise RewindError("checkpoint() must precede rewind()")
        return self._session.rewind_to(len(self._checkpoint_tokens))

    def do_again(self, messages: list[dict[str, str]]) -> tuple[str, BranchStats]:
        """Rewind to the checkpoint and run a different turn."""

        self.rewind()
        return self.act(messages)

    def close(self) -> None:
        if self._closed:
            return
        self._session.close()
        self._closed = True
